const int default_dynlib_len = sizeof(default_dynlib) / sizeof(default_dynlib[0]);

static int same(const char *a, const char *b) {
  while (*a && *a == *b)
    a++, b++;
  return *a == *b;
}

uintptr_t dynlib_lookup(const char *name) {
  for (int i = 0; i < default_dynlib_len; i++) {
    if (same(default_dynlib[i].symbol, name))
      return default_dynlib[i].func;
  }
  return 0;
}
